{
  "name": "job-workspace",
  "private": true,
  "type": "module",
  "workspaces": [
    "packages/*"
  ]
}

export function parseJob(input) {
  const job = JSON.parse(input);
  if (typeof job.id !== "string" || !job.id.trim()) throw new Error("Job id required");
  return { id: job.id.trim(), payload: job.payload };
}

import { parseJob } from "../../core/src/index.js";
export async function runJob(input, handler) {
  const job = parseJob(input);
  const result = await handler(job.payload);
  return { id: job.id, result };
}

import assert from "node:assert/strict";
import { test } from "node:test";
import { runJob } from "../packages/worker/src/index.js";
test("passes payload and retains identity", async () => assert.deepEqual(await runJob(JSON.stringify({id:"  j1  ",payload:2}), async x => x*2), {id:"j1",result:4}));
test("propagates handler failure", async () => assert.rejects(runJob(JSON.stringify({id:"j1"}), async () => {throw new Error("failed");}), /failed/));

export function loadConfig(env = process.env) {
  const port = Number(env.PORT ?? 3000);
  if (!Number.isInteger(port) || port < 1 || port > 65535) throw new Error("Invalid PORT");
  return { port, prefix: env.GREETING_PREFIX ?? "Hello" };
}

export function handle(url, config) {
  if (url.pathname === "/health") return {status:200,body:{ok:true}};
  if (url.pathname === "/greet") return {status:200,body:{message:`${config.prefix}, ${url.searchParams.get("name") ?? "world"}`}};
  return {status:404,body:{error:"Not found"}};
}

import http from "node:http";
import { loadConfig } from "./config.js";
import { handle } from "./handler.js";
const config = loadConfig();
http.createServer((req,res) => {
  const result = handle(new URL(req.url, "http://localhost"), config);
  res.writeHead(result.status, {"content-type":"application/json"});
  res.end(JSON.stringify(result.body));
}).listen(config.port);

import assert from "node:assert/strict";
import { test } from "node:test";
import { loadConfig } from "../src/config.js";
import { handle } from "../src/handler.js";
test("default config", () => assert.deepEqual(loadConfig({}), {port:3000,prefix:"Hello"}));
test("invalid port", () => assert.throws(() => loadConfig({PORT:"no"}), /Invalid PORT/));
test("greeting", () => assert.deepEqual(handle(new URL("http://local/greet?name=Ada"), loadConfig({})), {status:200,body:{message:"Hello, Ada"}}));

