export function loadConfig(env = process.env) {
  const port = Number(env.PORT ?? 3100);
  if (!Number.isInteger(port) || port < 1 || port > 65535) throw new Error("Invalid PORT");
  return { port, prefix: env.GREETING_PREFIX ?? "Hello" };
}

export function handle(url, config) {
  if (url.pathname === "/health") return {status:200,body:{ok:true}};
  if (url.pathname === "/greet") return {status:200,body:{greeting:`${config.prefix}, ${url.searchParams.get("name") ?? "world"}`}};
  return {status:404,body:{error:"Not found"}};
}

import http from "node:http";
import { loadConfig } from "./config.js";
import { handle } from "./handler.js";
const config = loadConfig();
http.createServer((req,res) => {
  const result = handle(new URL(req.url, "http://localhost"), config);
  res.writeHead(result.status, {"content-type":"application/json"});
  res.end(JSON.stringify(result.body));
}).listen(config.port);

import assert from "node:assert/strict";
import { test } from "node:test";
import { loadConfig } from "../src/config.js";
import { handle } from "../src/handler.js";
test("default config", () => assert.deepEqual(loadConfig({}), {port:3100,prefix:"Hello"}));
test("invalid port", () => assert.throws(() => loadConfig({PORT:"no"}), /Invalid PORT/));
test("greeting", () => assert.deepEqual(handle(new URL("http://local/greet?name=Ada"), loadConfig({})), {status:200,body:{greeting:"Hello, Ada"}}));

export function createCache(ttl = 5000, now = Date.now) {
  const values = new Map();
  return {
    getOrSet(key, make) {
      const entry = values.get(key);
      if (entry && entry.until > now()) return entry.value;
      const value = make();
      values.set(key, {value, until:now()+ttl});
      return value;
    },
    clear() { values.clear(); }
  };
}

import assert from "node:assert/strict";
import { test } from "node:test";
import { createCache } from "../src/cache.js";
test("expires at the TTL boundary", () => {let clock=0; const cache=createCache(5000,()=>clock); assert.equal(cache.getOrSet("a",()=>1),1); clock=4999; assert.equal(cache.getOrSet("a",()=>2),1); clock=5000; assert.equal(cache.getOrSet("a",()=>3),3);});

